<?php
declare(strict_types=1);

require_once __DIR__ . '/../fpdf/fpdf.php';

/*
 * SHARED PDF REPORT BUILDER (FPDF, already used by the clinic's reports).
 * Every report PDF has:
 *  - a header with the logo, clinic name, report title, branch, period and
 *    filters, "Generated by <name> (<role>)" and the Manila date and time;
 *  - tables with the column headers repeated on every page, text that
 *    wraps instead of being cut, landscape for wide tables;
 *  - all rows of the filters (never a screen page), totals and summaries;
 *  - "Page X of Y" in the footer, and nothing from the browser.
 * Text is converted from UTF-8 to Windows-1252 (the core fonts' encoding)
 * so "–", "ñ" and "é" print correctly; a cell that is only "✓" is drawn
 * as a drawn check mark.
 *
 * A report is an array (see sources/report_export.php):
 *   title, orientation ('P'|'L'), summary [label => value],
 *   sections [ [title?, columns [[label, width, align]], rows [[cells]], totals?, empty?] ],
 *   notes [text]
 */

const REPORT_CLINIC_NAME = 'SBI Medical and Animal Bite Center';
const REPORT_CLINIC_SUBTITLE = 'and Vaccination Clinic';

/** UTF-8 text for FPDF core fonts (Windows-1252). */
function reportPdfEncode($value): string
{
    $text = (string)$value;
    $text = str_replace(["\r\n", "\r"], "\n", $text);
    $text = str_replace(['✓', '✔', '→', '≥', '≤', '•'], ['Yes', 'Yes', '->', '>=', '<=', '-'], $text);
    $converted = function_exists('iconv') ? @iconv('UTF-8', 'Windows-1252//TRANSLIT//IGNORE', $text) : false;
    if ($converted === false) $converted = mb_convert_encoding($text, 'Windows-1252', 'UTF-8');
    return $converted;
}

class SbcReportPdf extends FPDF
{
    private array $meta;
    private array $tableColumns = [];
    private array $tableWidths = [];
    private bool $inTable = false;
    private float $lineHeight = 4.2;
    private float $bodyFont = 8;

    /** $meta: title, branch, period, filters, generated_by, generated_at, orientation */
    public function __construct(array $meta)
    {
        $orientation = strtoupper((string)($meta['orientation'] ?? 'P')) === 'L' ? 'L' : 'P';
        parent::__construct($orientation, 'mm', 'A4');
        $this->meta = $meta;
        $margin = (float)($meta['margin'] ?? 12);
        $this->SetMargins($margin, 12, $margin);
        $this->SetAutoPageBreak(true, 18);
        $this->AliasNbPages('{nb}');
        $this->SetTitle(reportPdfEncode((string)($meta['title'] ?? 'Report')));
        $this->SetAuthor(reportPdfEncode(REPORT_CLINIC_NAME));
        $this->SetCreator('SmartBiteCare');
        $this->AddPage();
    }

    private function usableWidth(): float
    {
        return $this->GetPageWidth() - $this->lMargin - $this->rMargin;
    }

    public function Header(): void
    {
        $w = $this->usableWidth();
        if ($this->PageNo() === 1) {
            $logo = __DIR__ . '/../logo.png';
            if (is_file($logo)) $this->Image($logo, $this->lMargin, 9, 18);
            $this->SetXY($this->lMargin + 22, 9);
            $this->SetFont('Helvetica', 'B', 13);
            $this->SetTextColor(43, 58, 140);
            $this->Cell($w - 22, 6, reportPdfEncode(mb_strtoupper(REPORT_CLINIC_NAME)), 0, 2, 'L');
            $this->SetFont('Helvetica', '', 9);
            $this->SetTextColor(90, 90, 90);
            $this->Cell($w - 22, 4.5, reportPdfEncode(REPORT_CLINIC_SUBTITLE . ' · Branch: ' . ($this->meta['branch'] ?? '')), 0, 2, 'L');
            $this->SetFont('Helvetica', 'B', 14);
            $this->SetTextColor(43, 58, 140);
            $this->Cell($w - 22, 7, reportPdfEncode((string)($this->meta['title'] ?? 'Report')), 0, 2, 'L');
            $this->SetX($this->lMargin);
            $this->SetY(max($this->GetY(), 28));
            $this->SetFont('Helvetica', '', 8.5);
            $this->SetTextColor(60, 60, 60);
            $lines = [];
            if (($this->meta['period'] ?? '') !== '') $lines[] = 'Period: ' . $this->meta['period'];
            if (($this->meta['filters'] ?? '') !== '') $lines[] = 'Filters: ' . $this->meta['filters'];
            $lines[] = 'Generated by ' . ($this->meta['generated_by'] ?? '') . ' on ' . ($this->meta['generated_at'] ?? '') . ' (Manila time)';
            foreach ($lines as $line) $this->MultiCell($w, 4.2, reportPdfEncode($line), 0, 'L');
            $this->SetDrawColor(43, 58, 140);
            $this->SetLineWidth(0.5);
            $this->Line($this->lMargin, $this->GetY() + 1.5, $this->lMargin + $w, $this->GetY() + 1.5);
            $this->Ln(4);
        } else {
            $this->SetFont('Helvetica', 'B', 9);
            $this->SetTextColor(43, 58, 140);
            $this->Cell($w * 0.6, 5, reportPdfEncode((string)($this->meta['title'] ?? 'Report')), 0, 0, 'L');
            $this->SetFont('Helvetica', '', 8);
            $this->SetTextColor(90, 90, 90);
            $this->Cell($w * 0.4, 5, reportPdfEncode(($this->meta['branch'] ?? '') . (($this->meta['period'] ?? '') !== '' ? ' · ' . $this->meta['period'] : '')), 0, 1, 'R');
            $this->SetDrawColor(200, 200, 200);
            $this->SetLineWidth(0.2);
            $this->Line($this->lMargin, $this->GetY() + 0.5, $this->lMargin + $w, $this->GetY() + 0.5);
            $this->Ln(2.5);
        }
        // A table that continues on this page repeats its column headers.
        if ($this->inTable) $this->tableHeader();
    }

    public function Footer(): void
    {
        $this->SetY(-12);
        $this->SetFont('Helvetica', '', 7.5);
        $this->SetTextColor(130, 130, 130);
        $w = $this->usableWidth();
        $this->Cell($w / 2, 5, reportPdfEncode('SmartBiteCare · ' . ($this->meta['title'] ?? '') . ' · Generated ' . ($this->meta['generated_at'] ?? '')), 0, 0, 'L');
        $this->Cell($w / 2, 5, 'Page ' . $this->PageNo() . ' of {nb}', 0, 0, 'R');
    }

    /** Summary block: label/value pairs in a grid. */
    public function summary(array $pairs, string $title = 'Summary'): void
    {
        if (!$pairs) return;
        $w = $this->usableWidth();
        $perRow = $this->DefOrientation === 'L' ? 4 : 3;
        $cellW = $w / $perRow;
        $this->SetFont('Helvetica', 'B', 9);
        $this->SetTextColor(43, 58, 140);
        $this->Cell($w, 6, reportPdfEncode($title), 0, 1, 'L');
        $this->SetFillColor(240, 244, 255);
        $i = 0;
        $pairs = array_map(null, array_keys($pairs), array_values($pairs));
        foreach (array_chunk($pairs, $perRow) as $chunk) {
            if ($this->GetY() + 10 > $this->PageBreakTrigger) $this->AddPage();
            $y = $this->GetY();
            foreach ($chunk as $j => [$label, $value]) {
                $x = $this->lMargin + $j * $cellW;
                $this->Rect($x, $y, $cellW - 2, 10, 'F');
                $this->SetXY($x + 2, $y + 1);
                $this->SetFont('Helvetica', '', 7.5);
                $this->SetTextColor(90, 90, 90);
                $this->Cell($cellW - 6, 3.8, reportPdfEncode((string)$label), 0, 2, 'L');
                $this->SetFont('Helvetica', 'B', 10);
                $this->SetTextColor(43, 58, 140);
                $this->Cell($cellW - 6, 4.8, reportPdfEncode((string)$value), 0, 0, 'L');
                $i++;
            }
            $this->SetXY($this->lMargin, $y + 12);
        }
        $this->Ln(1);
    }

    /** Number of lines a text needs in a column of width $w (FPDF tutorial algorithm). */
    private function nbLines(float $w, string $txt): int
    {
        $cw = $this->CurrentFont['cw'];
        $wmax = ($w - 2 * $this->cMargin) * 1000 / $this->FontSize;
        $s = str_replace("\r", '', $txt);
        $nb = strlen($s);
        if ($nb > 0 && $s[$nb - 1] === "\n") $nb--;
        $sep = -1; $i = 0; $j = 0; $l = 0; $nl = 1;
        while ($i < $nb) {
            $c = $s[$i];
            if ($c === "\n") { $i++; $sep = -1; $j = $i; $l = 0; $nl++; continue; }
            if ($c === ' ') $sep = $i;
            $l += $cw[$c] ?? 500;
            if ($l > $wmax) {
                if ($sep === -1) { if ($i === $j) $i++; } else { $i = $sep + 1; }
                $sep = -1; $j = $i; $l = 0; $nl++;
            } else {
                $i++;
            }
        }
        return $nl;
    }

    private function tableHeader(): void
    {
        $this->SetFont('Helvetica', 'B', $this->bodyFont);
        $this->SetFillColor(43, 58, 140);
        $this->SetTextColor(255, 255, 255);
        $this->SetDrawColor(43, 58, 140);
        $this->SetLineWidth(0.2);
        $lines = 1;
        foreach ($this->tableColumns as $i => $col) {
            $lines = max($lines, $this->nbLines($this->tableWidths[$i], reportPdfEncode($col['label'])));
        }
        $h = $lines * $this->lineHeight + 2;
        $x = $this->lMargin;
        $y = $this->GetY();
        foreach ($this->tableColumns as $i => $col) {
            $w = $this->tableWidths[$i];
            $this->Rect($x, $y, $w, $h, 'DF');
            $this->SetXY($x, $y + 1);
            $this->MultiCell($w, $this->lineHeight, reportPdfEncode($col['label']), 0, 'C');
            $x += $w;
        }
        $this->SetXY($this->lMargin, $y + $h);
    }

    /** One table: repeated header on new pages, wrapped cells, optional totals row. */
    public function table(array $section): void
    {
        $columns = array_values(array_filter($section['columns'], static fn($c) => empty($c['screen_only'])));
        $keep = [];
        foreach ($section['columns'] as $i => $c) if (empty($c['screen_only'])) $keep[] = $i;
        $rows = array_map(static fn($r) => array_map(static fn($k) => $r[$k] ?? '', $keep), $section['rows']);
        $totals = isset($section['totals']) ? array_map(static fn($k) => $section['totals'][$k] ?? '', $keep) : null;

        $w = $this->usableWidth();
        $sum = array_sum(array_map(static fn($c) => (float)($c['width'] ?? 1), $columns)) ?: 1;
        $this->tableColumns = $columns;
        $this->tableWidths = array_map(static fn($c) => $w * (float)($c['width'] ?? 1) / $sum, $columns);
        // Font: the section's own size, else smaller for wide tables.
        $this->bodyFont = isset($section['font']) ? (float)$section['font'] : (count($columns) > 14 ? 6 : (count($columns) > 10 ? 7 : 8));
        $this->lineHeight = round($this->bodyFont * 0.53, 2);

        if (!empty($section['title'])) {
            if ($this->GetY() + 20 > $this->PageBreakTrigger) $this->AddPage();
            $this->SetFont('Helvetica', 'B', 10);
            $this->SetTextColor(43, 58, 140);
            $this->Cell($w, 6, reportPdfEncode((string)$section['title']), 0, 1, 'L');
        }
        if ($this->GetY() + 18 > $this->PageBreakTrigger) $this->AddPage();
        $this->tableHeader();
        $this->inTable = true;

        if (!$rows) {
            $this->SetFont('Helvetica', 'I', 8.5);
            $this->SetTextColor(110, 110, 110);
            $this->SetDrawColor(220, 220, 220);
            $this->Cell($w, 8, reportPdfEncode((string)($section['empty'] ?? 'No records match the selected filters.')), 1, 1, 'C');
        }
        $fill = false;
        foreach ($rows as $row) {
            $this->tableRow($row, $fill, false);
            $fill = !$fill;
        }
        if ($totals !== null) $this->tableRow($totals, false, true);
        $this->inTable = false;
        $this->Ln(4);
    }

    private function tableRow(array $row, bool $fill, bool $bold): void
    {
        $this->SetFont('Helvetica', $bold ? 'B' : '', $this->bodyFont);
        $cells = array_map('reportPdfEncode', $row);
        $lines = 1;
        foreach ($cells as $i => $text) {
            if (!isset($this->tableWidths[$i])) continue;
            $lines = max($lines, $this->nbLines($this->tableWidths[$i], $text));
        }
        $h = $lines * $this->lineHeight + 1.6;
        if ($this->GetY() + $h > $this->PageBreakTrigger) {
            $this->AddPage(); // Header() repeats the column headers
            $this->SetFont('Helvetica', $bold ? 'B' : '', $this->bodyFont);
        }
        $x = $this->lMargin;
        $y = $this->GetY();
        $this->SetDrawColor(215, 220, 230);
        $this->SetTextColor(35, 35, 35);
        if ($bold) $this->SetFillColor(228, 233, 250); elseif ($fill) $this->SetFillColor(247, 249, 255); else $this->SetFillColor(255, 255, 255);
        foreach ($cells as $i => $text) {
            if (!isset($this->tableWidths[$i])) continue;
            $w = $this->tableWidths[$i];
            $align = strtoupper((string)($this->tableColumns[$i]['align'] ?? 'L'));
            $this->Rect($x, $y, $w, $h, 'DF');
            $raw = (string)$row[$i];
            if ($raw === '✓' || $raw === '✔') {
                // Drawn as lines, so every PDF viewer shows it (no symbol font needed).
                $size = max(1.6, $this->lineHeight * 0.75);
                $cx = $x + $w / 2;
                $cy = $y + $h / 2;
                $this->SetDrawColor(20, 110, 60);
                $this->SetLineWidth(0.35);
                $this->Line($cx - $size * 0.5, $cy, $cx - $size * 0.12, $cy + $size * 0.4);
                $this->Line($cx - $size * 0.12, $cy + $size * 0.4, $cx + $size * 0.55, $cy - $size * 0.45);
                $this->SetLineWidth(0.2);
                $this->SetDrawColor(215, 220, 230);
            } else {
                $this->SetXY($x, $y + 0.8);
                $this->MultiCell($w, $this->lineHeight, $text, 0, in_array($align, ['L', 'C', 'R'], true) ? $align : 'L');
            }
            $x += $w;
        }
        $this->SetXY($this->lMargin, $y + $h);
    }

    /** Legend / notes paragraphs. */
    public function notes(array $notes, string $title = 'Notes'): void
    {
        if (!$notes) return;
        $w = $this->usableWidth();
        if ($this->GetY() + 14 > $this->PageBreakTrigger) $this->AddPage();
        $this->SetFont('Helvetica', 'B', 9);
        $this->SetTextColor(43, 58, 140);
        $this->Cell($w, 6, reportPdfEncode($title), 0, 1, 'L');
        $this->SetFont('Helvetica', '', 8);
        $this->SetTextColor(60, 60, 60);
        foreach ($notes as $note) $this->MultiCell($w, 4, reportPdfEncode('- ' . $note), 0, 'L');
    }
}

/** Build the PDF of a report and return it as a string. */
function reportPdfBuild(array $report, array $meta): string
{
    $meta['orientation'] = $report['orientation'] ?? ($meta['orientation'] ?? 'P');
    $meta['title'] = $report['title'] ?? ($meta['title'] ?? 'Report');
    if (isset($report['margin'])) $meta['margin'] = $report['margin'];
    $pdf = new SbcReportPdf($meta);
    if (!empty($report['summary'])) $pdf->summary($report['summary'], (string)($report['summary_title'] ?? 'Summary'));
    foreach ($report['sections'] ?? [] as $section) $pdf->table($section);
    if (!empty($report['notes'])) $pdf->notes($report['notes'], (string)($report['notes_title'] ?? 'Notes'));
    return $pdf->Output('S');
}
